import {
  Group,
  Mesh,
  TorusKnotGeometry,
  CylinderGeometry,
  PlaneGeometry,
  DirectionalLight,
  GridHelper,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  SRGBColorSpace,
  RepeatWrapping
} from 'three/webgpu';
import {
  vec4,
  vec3,
  vec2,
  uv,
  texture,
  mix,
  uniform,
  positionLocal,
  smoothstep,
  val,
  mul,
  add
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' }
    ]
  };

  const timelines = [];

  // ---------------------------------------------------------
  // 1. BACKDROP STAGE
  // ---------------------------------------------------------
  const backdropGeo = new PlaneGeometry(14, 12);
  const backdropMat = new MeshBasicNodeMaterial();

  const uvPos = uv();
  const stop0 = colors.gradientStops[0]?.hex ?? '#0b0b10';
  const stop1 = colors.gradientStops[1]?.hex ?? '#101017';
  const stop2 = colors.gradientStops[2]?.hex ?? '#16161d';

  const t0 = vec3(new THREE.Color(stop0));
  const t1 = vec3(new THREE.Color(stop1));
  const t2 = vec3(new THREE.Color(stop2));

  const gradColor = mix(
    mix(t0, t1, smoothstep(0.0, 0.7, uvPos.y)),
    t2,
    smoothstep(0.7, 1.0, uvPos.y)
  );

  backdropMat.colorNode = vec4(gradColor, 1.0);
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -3);
  group.add(backdropMesh);

  // ---------------------------------------------------------
  // 2. CONTACT SHADOW PLANE
  // ---------------------------------------------------------
  const shadowGeo = new PlaneGeometry(4.0, 4.0);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  // Procedural soft radial gradient fallback node
  const radialDist = uvPos.sub(0.5).length();
  const shadowAlpha = smoothstep(0.375, 0.0, radialDist).mul(0.6);
  shadowMat.colorNode = vec4(vec3(0.0), shadowAlpha);

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.355, 0);
  group.add(shadowMesh);

  // ---------------------------------------------------------
  // 3. CYLINDRICAL PEDESTAL (Chambered Profile)
  // ---------------------------------------------------------
  // Smooth chamfered pedestal using 3 segments
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestalMesh = new Mesh(pedestalGeo, pedestalMat);
  pedestalMesh.position.set(0, -0.6, 0); // centered at y=-0.35 on its top face (0.5 tall -> -0.6 center)
  group.add(pedestalMesh);

  // ---------------------------------------------------------
  // 4. TORUS KNOT HERO SUBJECT
  // ---------------------------------------------------------
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: colors.paper,
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35
  });

  const subjectGroup = new Group();
  subjectGroup.position.set(0, 0.4, 0);
  group.add(subjectGroup);

  const tempKnotMesh = new Mesh(knotGeo, knotMat);
  subjectGroup.add(tempKnotMesh);

  // Load Brushed Texture with Swappings mitigation
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = RepeatWrapping;
      tex.wrapT = RepeatWrapping;
      tex.colorSpace = SRGBColorSpace;

      const texNode = texture(tex);
      const roughnessUniform = uniform(0.55);
      const compositeRoughness = mul(texNode.r, roughnessUniform).add(0.02); // 2% value jitter baked

      knotMat.roughnessNode = compositeRoughness;
      knotMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------------------------------------------------------
  // 5. LOCAL LIGHTING RIM PROFILE
  // ---------------------------------------------------------
  const studioKey = new DirectionalLight(colors.accent, 1.2);
  studioKey.position.set(3, 4, 2);
  group.add(studioKey);

  const studioRim = new DirectionalLight(colors.paper, 0.8);
  studioRim.position.set(-3, 2, -2);
  group.add(studioRim);

  // ---------------------------------------------------------
  // 6. TYPOGRAPHY
  // ---------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineString = "Material study 03";
  let captionString = "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT";

  items.forEach(item => {
    const role = (item.role ?? '').toLowerCase();
    const txt = item.text ?? '';
    if (role === 'headline' || role === 'title') {
      headlineString = txt;
    } else if (role === 'caption' || role === 'subhead') {
      captionString = txt.toUpperCase();
    }
  });

  // Headline placement (1.2 units below center)
  const headlineObj = ctx.fontAtlas.createText(headlineString, {
    fontSize: 32,
    color: colors.paper,
    align: 'center'
  });
  headlineObj.position.set(0, -1.2, 0.1);
  group.add(headlineObj);

  // Caption placement (1.6 units below center)
  const captionObj = ctx.fontAtlas.createText(captionString, {
    fontSize: 12,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 1.5
  });
  captionObj.position.set(0, -1.6, 0.15);
  group.add(captionObj);

  // ---------------------------------------------------------
  // 7. CINEMATIC PRIMITIVES & TIMELINES
  // ---------------------------------------------------------
  const primitives = config.cinematicPrimitives ?? [];
  primitives.forEach(prim => {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params);
      if (res) {
        if (res.timeline) timelines.push(res.timeline);
        if (res.cleanup) group.userData.cleanupHook = res.cleanup;
      }
    }
  });

  // Idle fallback or primary knot rotation (0.1 rad/s)
  const knotTl = gsap.timeline({ repeat: -1 });
  knotTl.to(tempKnotMesh.rotation, {
    y: Math.PI * 2,
    duration: (Math.PI * 2) / 0.1,
    ease: 'none'
  });
  timelines.push(knotTl);

  // ---------------------------------------------------------
  // CLEANUP DESTRUCTOR
  // ---------------------------------------------------------
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl && tl.kill());
    if (group.userData.cleanupHook) {
      group.userData.cleanupHook();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    pedestalGeo.dispose();
    pedestalMat.dispose();
    knotGeo.dispose();
    knotMat.dispose();
  };

  return group;
}
